const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Los Angeles geometry
  const laGeometry = ee.Geometry.Rectangle([-118.5, 33.8, -117.5, 34.3]);

  // 2. Define date ranges for October 1-23
  const startDate = '10-01';
  const endDate = '10-23';

  // Function to get NO2 data for a specific year
  function getNO2Data(year) {
    const dateStart = year + '-' + startDate;
    const dateEnd = year + '-' + endDate;

    const collection = ee.ImageCollection('COPERNICUS/S5P/TROPOMI/NO2')
      .filterBounds(laGeometry)
      .filterDate(dateStart, dateEnd)
      .select('NO2_column_number_density');

    return collection;
  }

  // 3. Collect data for each year
  const col2018 = getNO2Data('2018');
  const col2019 = getNO2Data('2019');
  const col2021 = getNO2Data('2021');

  const size2018 = col2018.size().getInfo();
  const size2019 = col2019.size().getInfo();
  const size2021 = col2021.size().getInfo();

  print('2018 Images: ' + size2018);
  print('2019 Images: ' + size2019);
  print('2021 Images: ' + size2021);

  // 4. Check for empty collections
  if (size2018 === 0 || size2019 === 0 || size2021 === 0) {
    print('Missing data for one or more years');
    print('C1');
    return;
  }

  // 5. Calculate mean NO2 for each year
  const mean2018 = col2018.mean();
  const mean2019 = col2019.mean();
  const mean2021 = col2021.mean();

  // 6. Get statistics with pixel counts
  const stats2018 = mean2018.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: laGeometry,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: laGeometry,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2021 = mean2021.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: laGeometry,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const no2_2018 = stats2018['NO2_column_number_density_mean'];
  const no2_2019 = stats2019['NO2_column_number_density_mean'];
  const no2_2021 = stats2021['NO2_column_number_density_mean'];

  const count2018 = stats2018['NO2_column_number_density_count'];
  const count2019 = stats2019['NO2_column_number_density_count'];
  const count2021 = stats2021['NO2_column_number_density_count'];

  // 7. Check for invalid values or no valid pixels
  if (no2_2018 === null || no2_2019 === null || no2_2021 === null) {
    print('Invalid NO2 values (null)');
    print('C3');
    return;
  }

  if (count2018 === 0 || count2019 === 0 || count2021 === 0) {
    print('No valid pixels after masking');
    print('C2');
    return;
  }

  // 8. Print statistics
  print('2018 NO2: ' + no2_2018.toFixed(6) + ' mol/m² (Pixels: ' + count2018 + ')');
  print('2019 NO2: ' + no2_2019.toFixed(6) + ' mol/m² (Pixels: ' + count2019 + ')');
  print('2021 NO2: ' + no2_2021.toFixed(6) + ' mol/m² (Pixels: ' + count2021 + ')');

  // 9. Compare: Is 2021 lower than both 2018 and 2019?
  if (no2_2021 < no2_2018 && no2_2021 < no2_2019) {
    print('2021 concentration is lower than both 2018 and 2019');
    print('A');
  } else {
    print('2021 concentration is NOT lower than both comparison years');
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
